def min_operations_to_increasing(n, k, a, b):
    if k == 0:
        # If no elements are in set b, it's impossible to change any element
        return -1 if not is_increasing(a) else 0

    # Set of indices that cannot be changed
    fixed_indices = set(b)

    # Function to check if the array is strictly increasing
    def is_increasing(arr):
        return all(arr[i] < arr[i + 1] for i in range(len(arr) - 1))

    # Check if the array is already strictly increasing
    if is_increasing(a):
        return 0

    # dp[i] will hold the minimum number of operations required to make a[0:i+1] increasing
    dp = [float('inf')] * n

    # Initialize the first element if it's not fixed
    if 1 not in fixed_indices:
        dp[0] = 0
    else:
        dp[0] = float('inf')  # Can't change a fixed element

    # Fill the dp array
    for i in range(1, n):
        if i + 1 in fixed_indices:
            # If current index is fixed, can only consider increasing up to the previous element
            if a[i] > a[i - 1]:
                dp[i] = dp[i - 1]
        else:
            # If current index is not fixed, we have a choice to change or not
            if a[i] > a[i - 1]:
                dp[i] = dp[i - 1]
            else:
                # We need to increase a[i] to be greater than a[i - 1]
                dp[i] = dp[i - 1] + 1

    # If we can make the whole array increasing, return the minimum operations
    if dp[-1] != float('inf'):
        return dp[-1]
    else:
        return -1

