def min_operations_to_increasing(n, k, a, b):
    # If k == 0, we can't change any elements, so check if the array is already increasing
    if k == 0:
        for i in range(1, n):
            if a[i] <= a[i - 1]:
                return -1
        return 0

    # Convert b to a set for O(1) membership checking
    b_set = set(b)

    # Calculate the number of elements that are already in increasing order
    already_sorted = 0
    for i in range(1, n):
        if a[i] > a[i - 1]:
            already_sorted += 1

    # Calculate the longest increasing subsequence of the non-b elements
    dp = []
    for i in range(n):
        if i + 1 not in b_set:
            num = a[i]
            # Binary search to find the insertion point
            left, right = 0, len(dp)
            while left < right:
                mid = (left + right) // 2
                if dp[mid] < num:
                    left = mid + 1
                else:
                    right = mid
            if left < len(dp):
                dp[left] = num
            else:
                dp.append(num)

    # The result is the total elements minus the length of the longest increasing subsequence
    # of non-b elements, minus the already sorted elements
    longest_increasing_subseq = len(dp)
    operations_needed = (n - longest_increasing_subseq) - already_sorted

    # If the operations needed is negative, it means we can make the array increasing
    return max(0, operations_needed)


